@php($editing = $editing ?? false)
<div x-data="userForm({{ $editing ? 'true' : 'false' }}, @js($id ?? null))" x-init="init()" x-cloak>
<div x-show="error" role="alert" class="mb-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div>
<form @submit.prevent="submit" class="space-y-5" novalidate><section class="rounded-2xl border border-border bg-white p-6 shadow-sm"><h3 class="font-semibold text-navy-900">Informasi pengguna internal</h3><div class="mt-5 grid gap-5 sm:grid-cols-2"><div><label class="field-label" for="user-name">Nama</label><input id="user-name" x-model="form.name" @input="error=''" class="field-input" required></div><div><label class="field-label" for="user-email">Email</label><input id="user-email" x-model="form.email" @input="error=''" type="email" class="field-input" required></div><div><label class="field-label" for="user-role">Role</label><select id="user-role" x-model="form.role" class="field-input"><option value="admin">Admin</option><option value="operator">Operator</option></select></div><div x-show="!editing"></div><div><label class="field-label" for="user-password">Password <span x-show="editing" class="font-normal text-slate-500">(opsional saat edit)</span></label><input id="user-password" x-model="form.password" type="password" class="field-input" :required="!editing"></div><div><label class="field-label" for="user-confirm">Konfirmasi password</label><input id="user-confirm" x-model="form.password_confirmation" type="password" class="field-input" :required="!editing"></div></div></section><div class="flex justify-end gap-3"><a href="{{ route('users.index') }}" class="action-button">Batal</a><button :disabled="saving" class="action-button-primary" type="submit" x-text="saving?'Menyimpan...':(editing?'Simpan perubahan':'Buat pengguna')">Buat pengguna</button></div></form></div>
<script>function userForm(editing,id){return{editing,id,saving:false,error:'',form:{name:'',email:'',password:'',password_confirmation:'',role:'operator'},async init(){if(this.$store.auth.role!=='admin'){location.href='/dashboard'}if(this.editing)try{this.form={...this.form,...(await window.axios.get(`/api/admin/users/${this.id}`)).data,password:'',password_confirmation:''}}catch(e){this.error=e.response?.data?.message||'Gagal memuat pengguna.'}},async submit(){if(!this.form.name.trim()){this.error='Nama wajib diisi.';return}if(!this.form.email.includes('@')){this.error='Email tidak valid.';return}if(!this.editing&&this.form.password.length<8){this.error='Password minimal 8 karakter.';return}if(this.form.password!==this.form.password_confirmation){this.error='Konfirmasi password tidak sama.';return}this.saving=true;this.error='';try{const url=this.editing?`/api/admin/users/${this.id}`:'/api/admin/users';const r=this.editing?window.axios.put(url,this.form):window.axios.post(url,this.form);await r;location.href='/users?success='+ (this.editing?'updated':'created')}catch(e){this.error=e.response?.data?.message||Object.values(e.response?.data?.errors||{}).flat().join(' ')||'Gagal menyimpan pengguna.'}finally{this.saving=false}}}}</script>
